// geometry.js mirrors internal/geometry/geometry.go exactly. The preview
// draws with these rules; the Go renderer applies the same rules through
// ffmpeg. test/geometry_cases.json (generated by the Go tests) pins the
// two implementations together.

export const FitFull = 'full'
export const FitCrop = 'crop'
export const FitBorder = 'border'

export const MAX_SCALED_DIM = 8192

export function normalizedSize(w, h, rotation) {
  const r = ((rotation % 360) + 360) % 360
  return r === 90 || r === 270 ? [h, w] : [w, h]
}

// displaySize derives true display dimensions from coded size, sample
// aspect ratio and rotation: width scales by SAR first, then rotation
// swaps axes. Non-positive SAR means unknown -> square pixels.
export function displaySize(storedW, storedH, sarNum, sarDen, rotation) {
  if (sarNum <= 0 || sarDen <= 0) {
    sarNum = 1
    sarDen = 1
  }
  const dw = Math.round((storedW * sarNum) / sarDen)
  const dh = storedH
  const r = ((rotation % 360) + 360) % 360
  return r === 90 || r === 270 ? [dh, dw] : [dw, dh]
}

const coverScale = (sw, sh, cw, ch) => Math.max(cw / sw, ch / sh)
const fitScale = (sw, sh, cw, ch) => Math.min(cw / sw, ch / sh)
const clamp01 = (v) => Math.min(1, Math.max(0, v))

// layoutFor computes canvas placement for a normalized source.
// Returns { fg, srcVisible, scale, complete, hasBackground } or throws.
export function layoutFor(sw, sh, cw, ch, mode, cropX = 0, cropY = 0) {
  if (sw <= 0 || sh <= 0 || cw <= 0 || ch <= 0) {
    throw new Error(`invalid dimensions: src ${sw}x${sh} canvas ${cw}x${ch}`)
  }
  if (mode === FitFull || mode === FitBorder) {
    const s = fitScale(sw, sh, cw, ch)
    const fw = sw * s, fh = sh * s
    return {
      fg: { x: (cw - fw) / 2, y: (ch - fh) / 2, w: fw, h: fh },
      srcVisible: { x: 0, y: 0, w: sw, h: sh },
      scale: s,
      complete: true,
      hasBackground: mode === FitBorder,
    }
  }
  if (mode === FitCrop) {
    const s = coverScale(sw, sh, cw, ch)
    const scaledW = sw * s, scaledH = sh * s
    if (scaledW > MAX_SCALED_DIM || scaledH > MAX_SCALED_DIM) {
      throw new Error(`crop scale ${s} overflows max scaled dimension`)
    }
    const vx = clamp01(cropX) * (scaledW - cw)
    const vy = clamp01(cropY) * (scaledH - ch)
    return {
      fg: { x: 0, y: 0, w: cw, h: ch },
      srcVisible: { x: vx / s, y: vy / s, w: cw / s, h: ch / s },
      scale: s,
      complete: false,
      hasBackground: false,
    }
  }
  throw new Error(`unknown fit mode ${mode}`)
}

// panViewport resolves the viewport origin inside the scaled image at
// progress t in [0,1]. Throws when the framing range is invalid.
export function panViewport(sw, sh, cw, ch, pan, t) {
  if (pan.zoom < 1) {
    throw new Error(`pan zoom ${pan.zoom} < 1: viewport would exceed image bounds`)
  }
  const s = coverScale(sw, sh, cw, ch) * pan.zoom
  const scaledW = sw * s, scaledH = sh * s
  if (scaledW > MAX_SCALED_DIM || scaledH > MAX_SCALED_DIM) {
    throw new Error('pan scale overflows max scaled dimension')
  }
  if (scaledW < cw || scaledH < ch) {
    throw new Error(`scaled image ${scaledW}x${scaledH} smaller than canvas`)
  }
  const overX = scaledW - cw, overY = scaledH - ch
  const x0 = clamp01(pan.x0) * overX, y0 = clamp01(pan.y0) * overY
  const x1 = clamp01(pan.x1) * overX, y1 = clamp01(pan.y1) * overY
  const tt = clamp01(t)
  return { vx: x0 + (x1 - x0) * tt, vy: y0 + (y1 - y0) * tt, scale: s }
}

export function validatePan(sw, sh, cw, ch, pan) {
  for (const t of [0, 0.5, 1]) panViewport(sw, sh, cw, ch, pan, t)
  return true
}

// even rounds to the nearest even integer (min 2), matching ffmpeg's
// yuv420p dimension requirement.
export function even(v) {
  let n = Math.round(v)
  if (n % 2 !== 0) n += 1
  return Math.max(2, n)
}
